import random
from collections import deque
from netgraph.graph import Graph

class Ref:  # naive edge-set reference
    def __init__(s, n): s.n=n; s.e=set()
    def add_edge(s,u,v): s.e.add((min(u,v),max(u,v)))
    def remove_edge(s,u,v):
        k=(min(u,v),max(u,v)); r=k in s.e; s.e.discard(k); return r
    def add_node(s): s.n+=1; return s.n-1
    def remove_node(s,u):
        f=lambda x: x-1 if x>u else x
        s.e={(f(a),f(b)) for a,b in s.e if a!=u and b!=u}; s.n-=1
    def edges(s): return sorted(s.e)
    def nb(s,u): return sorted({b if a==u else a for a,b in s.e if u in (a,b)})
    def dist(s,u,v):
        d={u:0}; q=deque([u])
        while q:
            c=q.popleft()
            for x in s.nb(c):
                if x not in d: d[x]=d[c]+1; q.append(x)
        return d.get(v)
    def comps(s):
        seen=set(); out=[]
        for st in range(s.n):
            if st in seen: continue
            c={st}; q=[st]; seen.add(st)
            while q:
                x=q.pop()
                for y in s.nb(x):
                    if y not in seen: seen.add(y); c.add(y); q.append(y)
            out.append(sorted(c))
        return out

random.seed(7)
for trial in range(300):
    n=random.randint(1,12); g=Graph(n); r=Ref(n)
    for _ in range(random.randint(5,60)):
        op=random.random()
        if op<0.5 and r.n:
            u,v=random.randrange(r.n),random.randrange(r.n); g.add_edge(u,v); r.add_edge(u,v)
        elif op<0.65 and r.n:
            u,v=random.randrange(r.n),random.randrange(r.n); assert g.remove_edge(u,v)==r.remove_edge(u,v)
        elif op<0.8:
            assert g.add_node()==r.add_node()
        elif r.n>1:
            u=random.randrange(r.n); g.remove_node(u); r.remove_node(u)
        assert g.node_count()==r.n
        assert g.edges()==r.edges(), (g.edges(), r.edges())
        assert g.edge_count()==len(r.e)
        for u in range(r.n):
            assert g.neighbors(u)==r.nb(u); assert g.degree(u)==len(r.nb(u))
            for v in range(r.n):
                assert g.has_edge(u,v)==((min(u,v),max(u,v)) in r.e)
                p=g.shortest_path(u,v); d=r.dist(u,v)
                if d is None: assert p is None
                else:
                    assert len(p)==d+1 and p[0]==u and p[-1]==v
                    assert all(g.has_edge(a,b) for a,b in zip(p,p[1:]))
        assert g.connected_components()==r.comps()
print("300 randomized trials: bitset Graph matches naive reference")
