import time, random
from netgraph.graph import Graph, _bits

n=2000
random.seed(1)
pairs=[(u,v) for u in range(n) for v in range(u,n) if random.random()<0.9]

class SetGraph:  # the previous implementation's add_edge, verbatim in spirit
    def __init__(s,n): s._adj=[set() for _ in range(n)]; s.c=0
    def add_edge(s,u,v):
        if v in s._adj[u]: return
        s._adj[u].add(v); s._adj[v].add(u); s.c+=1
class ByteGraph:
    def __init__(s,n): s._rows=[bytearray(n) for _ in range(n)]; s.c=0
    def add_edge(s,u,v):
        if s._rows[u][v]: return
        s._rows[u][v]=1; s._rows[v][u]=1; s.c+=1

for name,cls in [("bitset (current)",Graph),("adjacency sets (old)",SetGraph),("bytearray rows",ByteGraph)]:
    g=cls(n); t=time.perf_counter()
    for u,v in pairs: g.add_edge(u,v)
    print(f"{name:22s} build {len(pairs)} edges: {time.perf_counter()-t:.2f}s")

g=Graph(n)
for u,v in pairs: g.add_edge(u,v)

def bits_str(row):
    s=f"{row:b}"; L=len(s)-1
    return [L-i for i in range(L,-1,-1) if s[i]=="1"]
def bits_find(row):
    s=f"{row:b}"[::-1]; out=[]; i=s.find("1")
    while i!=-1: out.append(i); i=s.find("1",i+1)
    return out
row=g._rows[0]
assert list(_bits(row))==bits_str(row)==bits_find(row)
for name,fn in [("_bits big-int loop",lambda:list(_bits(row))),("bin() scan",lambda:bits_str(row)),("bin()+find",lambda:bits_find(row))]:
